package mrpapermoon.whisper.mesh.nearbyimport kotlinx.serialization.InternalSerializationApiimport kotlinx.serialization.Serializableimport mrpapermoon.whisper.mesh.db.NetworkMessageEntityimport mrpapermoon.whisper.mesh.db.WhispererEntity@InternalSerializationApi @Serializableinternal sealed class NearbyMessage {	@InternalSerializationApi @Serializable	class Greeting(val version: Short, val decryptionKey: ByteArray) : NearbyMessage()	@InternalSerializationApi @Serializable	open class ContactsRequest(val whispererIds: List<String>) : NearbyMessage()	@InternalSerializationApi @Serializable	class ContactsResponse(val contacts: List<WhispererEntity>) : NearbyMessage()	@InternalSerializationApi @Serializable	class RumorsRequest(val whispererIds: List<String>) : NearbyMessage()	@InternalSerializationApi @Serializable	class RumorsResponse(val rumors: List<NetworkMessageEntity>) : NearbyMessage()	@InternalSerializationApi @Serializable	object Gratitude : NearbyMessage()	companion object {		const val VERSION: Short = 1	}}